 49			ProjectGenerationResponse response = this.initializrService.generate(request);
 50			String fileName = (request.getOutput() != null) ? request.getOutput() : response.getFileName();
 51			if (shouldExtract(request, response)) {
 52				if (isZipArchive(response)) {
 53					extractProject(response, request.getOutput(), force);
 54					return;
 55				}
 56				else {
 57					Log.info("Could not extract '" + response.getContentType() + "'");
 58					// Use value from the server since we can't extract it
 59					fileName = response.getFileName();
 60				}
 61			}
 62			if (fileName == null) {
 63				throw new ReportableException("Could not save the project, the server did not set a preferred "
 64						+ "file name and no location was set. Specify the output location for the project.");
 65			}
 66			writeProject(response, fileName, force);
 67		}
 68	
 69		/**
 70		 * Detect if the project should be extracted.
 71		 * @param request the generation request
 72		 * @param response the generation response
 73		 * @return if the project should be extracted
 74		 */
 75		private boolean shouldExtract(ProjectGenerationRequest request, ProjectGenerationResponse response) {
 76			if (request.isExtract()) {
 77				return true;
 78			}
 79			// explicit name hasn't been provided for an archive and there is no extension
 80			return isZipArchive(response) && request.getOutput() != null && !request.getOutput().contains(".");
 81		}
 82	
 83		private boolean isZipArchive(ProjectGenerationResponse entity) {
 84			if (entity.getContentType() != null) {
 85				try {
 86					return ZIP_MIME_TYPE.equals(entity.getContentType().getMimeType());
 87				}
 88				catch (Exception ex) {
 89					// Ignore
 90				}
 91			}
 92			return false;
 93		}
