 95		private void extractProject(ProjectGenerationResponse entity, @Nullable String output, boolean overwrite)
 96				throws IOException {
 97			File outputDirectory = (output != null) ? new File(output) : new File(System.getProperty("user.dir"));
 98			createDirectories(outputDirectory);
 99			byte[] content = entity.getContent();
100			Assert.state(content != null, "'content' must not be null");
101			try (ZipInputStream zipStream = new ZipInputStream(new ByteArrayInputStream(content))) {
102				extractFromStream(zipStream, overwrite, outputDirectory);
103				fixExecutableFlag(outputDirectory, "mvnw");
104				fixExecutableFlag(outputDirectory, "gradlew");
105				Log.info("Project extracted to '" + outputDirectory.getAbsolutePath() + "'");
106			}
107		}
108	
109		private void extractFromStream(ZipInputStream zipStream, boolean overwrite, File outputDirectory)
110				throws IOException {
111			String canonicalOutputPath = outputDirectory.getCanonicalPath() + File.separator;
112			for (ZipEntry entry; (entry = zipStream.getNextEntry()) != null;) {
113				File file = createOutputFile(outputDirectory, canonicalOutputPath, entry);
114				assertOverwriteAllowed(file, overwrite);
115				if (entry.isDirectory()) {
116					createDirectories(file);
117				}
118				else {
119					createDirectories(file.getParentFile());
120					try (FileOutputStream outputStream = new FileOutputStream(file)) {
121						FileCopyUtils.copy(StreamUtils.nonClosing(zipStream), outputStream);
122					}
123				}
124				zipStream.closeEntry();
125			}
126		}
127	
128		private File createOutputFile(File outputDirectory, String canonicalOutputPath, ZipEntry entry) throws IOException {
129			File file = new File(outputDirectory, entry.getName());
130			String canonicalEntryPath = file.getCanonicalPath();
131			if (!canonicalEntryPath.startsWith(canonicalOutputPath)) {
132				throw new ReportableException("Entry '" + entry.getName() + "' would be written to '" + canonicalEntryPath
133						+ "'. This is outside the output location of '" + canonicalOutputPath
134						+ "'. Verify your target server configuration.");
135			}
136			return file;
137		}
138	
139		private void assertOverwriteAllowed(File file, boolean overwrite) {
140			if (file.exists() && !overwrite) {
141				throw new ReportableException((file.isDirectory() ? "Directory" : "File") + " '" + file.getName()
142						+ "' already exists. Use --force if you want to overwrite or specify an alternate location.");
143			}
144		}
145	
146		private void createDirectories(@Nullable File directory) {
147			if (directory == null) {
148				return;
149			}
150			if (directory.exists()) {
151				if (!directory.isDirectory()) {
152					throw new ReportableException("Path '" + directory.getPath() + "' exists but is not a directory");
153				}
154				return;
155			}
156			if (!directory.mkdirs() && !directory.isDirectory()) {
157				throw new ReportableException("Failed to create directory '" + directory.getPath() + "'");
158			}
159		}
160	
161		private void writeProject(ProjectGenerationResponse entity, String output, boolean overwrite) throws IOException {
162			File outputFile = new File(System.getProperty("user.dir"), output);
163			if (outputFile.exists()) {
164				if (!overwrite) {
165					throw new ReportableException(
166							"File '" + outputFile.getName() + "' already exists. Use --force if you want to "
167									+ "overwrite or specify an alternate location.");
168				}
169				if (!outputFile.delete()) {
170					throw new ReportableException("Failed to delete existing file " + outputFile.getPath());
171				}
172			}
173			byte[] content = entity.getContent();
174			Assert.state(content != null, "'content' must not be null");
175			FileCopyUtils.copy(content, outputFile);
176			Log.info("Content saved to '" + output + "'");
177		}
178	
179		private void fixExecutableFlag(File dir, String fileName) {
180			File f = new File(dir, fileName);
181			if (f.exists()) {
182				f.setExecutable(true, false);
183			}
184		}
